import java.util.*;
import java.io.*;

public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        InputStreamReader isr = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(isr);
        PrintWriter pw = new PrintWriter(System.out);
        String patternStr = br.readLine();
        int maxVal = 1;
        for (int i = 0; i < patternStr.length(); i++) {
            maxVal *= 10;
        }
        int countMatches = 0;
        for (int candidate = 0; candidate < maxVal; candidate += 25) {
            if (matchesPattern(patternStr, candidate)) {
                countMatches++;
            }
        }
        pw.println(countMatches);
        pw.flush();
    }

    public static boolean matchesPattern(String pattern, int number) {
        int lastDigit = -1;
        for (int i = pattern.length() - 1; i >= 0; i--) {
            int digitInNumber = number % 10;
            char c = pattern.charAt(i);
            if (c == 'X') {
                if (lastDigit >= 0 && lastDigit != digitInNumber) {
                    return false;
                }
                lastDigit = digitInNumber;
            } else if (c != '_') {
                if (c - '0' != digitInNumber) {
                    return false;
                }
            }
            if (pattern.length() > 1 && i == 0 && digitInNumber == 0) {
                return false;
            }
            number /= 10;
        }
        return true;
    }
}
